package com.hospital.platform.bootstrap;
import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.http.HttpHeaders; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class CorsAndRedisIntegrationTest { @Autowired MockMvc mvc; @Autowired StringRedisTemplate redis; @Test void allowsConfiguredOriginsAndRejectsOtherOrigin()throws Exception{for(String origin:java.util.List.of("http://localhost:5173","http://127.0.0.1:5173")){var response=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.options("/api/v1/auth/login").header(HttpHeaders.ORIGIN,origin).header(HttpHeaders.ACCESS_CONTROL_REQUEST_METHOD,"POST").header(HttpHeaders.ACCESS_CONTROL_REQUEST_HEADERS,"authorization,content-type")).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(200);assertThat(response.getHeader(HttpHeaders.ACCESS_CONTROL_ALLOW_ORIGIN)).isEqualTo(origin);}var denied=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.options("/api/v1/auth/login").header(HttpHeaders.ORIGIN,"https://invalid.example").header(HttpHeaders.ACCESS_CONTROL_REQUEST_METHOD,"POST")).andReturn().getResponse();assertThat(denied.getStatus()).isEqualTo(403);}
 @Test void usesRealRedisForJsonStringDeleteAndExpiration()throws Exception{String key="hospital:test:iam:redis:integration:"+java.util.UUID.randomUUID();String json="{\"id\":\"redis-test\",\"name\":\"payload\"}";redis.opsForValue().set(key,json,java.time.Duration.ofSeconds(2));assertThat(redis.opsForValue().get(key)).isEqualTo(json);assertThat(redis.getExpire(key)).isPositive();Thread.sleep(2500);assertThat(redis.hasKey(key)).isFalse();redis.opsForValue().set(key,json);assertThat(redis.delete(key)).isTrue();assertThat(redis.hasKey(key)).isFalse();}}
